INSERT INTO public.recipes (title, description, ingredients, steps, prep_time_minutes, categories, image_url) VALUES
('პასტა კარბონარა', 'რომაული კლასიკა — სპაგეტი, კვერცხის გული, პეკორინო და გუანჩალე. კრემი არასდროს!',
 '["სპაგეტი 400 გრ","გუანჩალე ან ბეკონი 150 გრ","კვერცხის გული 4 ცალი","პეკორინო რომანო 80 გრ","შავი წიწაკა","მარილი"]'::jsonb,
 '["დიდი ქვაბით ადუღეთ დამარილებული წყალი და მოხარშეთ სპაგეტი al dente.","გუანჩალე დაჭერით კუბიკებად და შეწვით ცხელ ტაფაზე მკვრივ ქერქამდე.","ცალკე თასში აურიეთ კვერცხის გულები, გახეხილი პეკორინო და უხვად წიწაკა.","ცხელი პასტა ჩააგდეთ ტაფაში გუანჩალესთან, გამორთეთ ცეცხლი.","ჩაასხით კვერცხის ნაზავი და სწრაფად აურიეთ, ცოტა პასტის წყალი დაუმატეთ კრემისებრ სოუსამდე.","მიაწოდეთ დაუყოვნებლივ ზემოდან პეკორინოს მოყრით."]'::jsonb,
 25, ARRAY['lunch','dinner'], 'https://images.unsplash.com/photo-1612874742237-6526221588e3?w=1200&q=80'),
('სუში ლოსოსით', 'იაპონური ნიგირი — თბილი ბრინჯი და ცივი ლოსოსის ნაჭერი, ვასაბით და სოიოს სოუსით.',
 '["სუშის ბრინჯი 300 გრ","ბრინჯის ძმარი 3 კოვზი","შაქარი 2 კოვზი","მარილი 1 ჩ.კ.","ახალი ლოსოსი 200 გრ","ვასაბი","სოიოს სოუსი","ჯანჯაფილი მარინადში"]'::jsonb,
 '["ბრინჯი გარეცხეთ სუფთა წყლამდე და მოხარშეთ.","ცხელ ბრინჯს დაუმატეთ ძმრის, შაქრისა და მარილის ნაზავი, ფაქიზად აურიეთ.","ლოსოსი დაჭერით 1 სმ სისქის ნაჭრებად ირიბად.","სველი ხელით ჩამოაყალიბეთ ბრინჯის პატარა ბალიშები.","თითოეულს დაუსვით ცოტა ვასაბი და დაადეთ ლოსოსის ნაჭერი.","მიაწოდეთ სოიოს სოუსთან და მარინადებულ ჯანჯაფილთან."]'::jsonb,
 50, ARRAY['lunch','dinner'], 'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?w=1200&q=80'),
('ტაკო კარნიტასით', 'მექსიკური ქუჩის საჭმელი — ნელ ცეცხლზე მოხარშული ღორის ხორცი, სიმინდის ტორტიაზე.',
 '["ღორის მხარი 1 კგ","ფორთოხალი 1 ცალი","ხახვი 1 ცალი","ნიორი 4 კბილი","ძირაკი 1 ჩ.კ.","ორეგანო 1 ჩ.კ.","სიმინდის ტორტია 12 ცალი","ქინძი","ლაიმი","წითელი ხახვი","მარილი"]'::jsonb,
 '["ღორის ხორცი დაჭერით დიდ კუბიკებად, დაამარილეთ და მოაყარეთ ძირაკი და ორეგანო.","ჩაწყევით ქვაბში, დაუმატეთ ხახვი, ნიორი და ფორთოხლის წვენი და ქერქი.","დახურეთ და მოხარშეთ ნელ ცეცხლზე 3 საათი სანამ არ დაიშლება.","ხორცი დაფშვნით ჩანგლით და შეწვით ცხელ ტაფაზე ხრაშუნიან ქერქამდე.","ტორტიები გაათბეთ მშრალ ტაფაზე.","ჩააწყვეთ ხორცი, დაუმატეთ დაჭრილი წითელი ხახვი, ქინძი და ლაიმის წვენი."]'::jsonb,
 200, ARRAY['lunch','dinner'], 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?w=1200&q=80'),
('ინდური ჩიქენ ტიკა მასალა', 'ბრიტანულ-ინდური კლასიკა — მარინადებული ქათამი კრემისებრ პომიდვრის სოუსში.',
 '["ქათმის მკერდი 600 გრ","იოგურტი 200 გრ","ჯანჯაფილი-ნიორის პასტა 2 კოვზი","გარამ მასალა 2 ჩ.კ.","პაპრიკა 1 კოვზი","კურკუმა 1 ჩ.კ.","პომიდვრის პიურე 400 გრ","კრემი 200 მლ","ხახვი 1 ცალი","კარაქი 40 გრ","ქინძი","ბრინჯი ბასმატი მიწოდებისთვის"]'::jsonb,
 '["ქათამი დაჭერით კუბიკებად და მარინადში (იოგურტი, პასტა, სანელებლების ნახევარი) დატოვეთ 1 საათი.","ცხელ ღუმელში ან ტაფაზე შეწვით ქათამი ქერქამდე.","ცალკე ტაფაზე კარაქზე მოშუშეთ ხახვი, დაუმატეთ დანარჩენი სანელებლები.","ჩაასხით პომიდვრის პიურე და მოხარშეთ 15 წუთი.","დაუმატეთ კრემი და ქათამი, მოხარშეთ კიდევ 10 წუთი.","მოაყარეთ ქინძი და მიაწოდეთ ბასმატის ბრინჯთან ერთად."]'::jsonb,
 75, ARRAY['dinner'], 'https://images.unsplash.com/photo-1565557623262-b51c2513a641?w=1200&q=80'),
('ფრანგული კრუასანი', 'მრავალშრიანი, კარაქიანი საუზმის კლასიკა პარიზული საცხობიდან.',
 '["ფქვილი 500 გრ","რძე 250 მლ","საფუარი 10 გრ","შაქარი 50 გრ","მარილი 10 გრ","კარაქი (მაღალხარისხოვანი) 250 გრ","კვერცხი 1 ცალი მოსაპირკეთებლად"]'::jsonb,
 '["თბილ რძეში გახსენით საფუარი და შაქარი, დაუმატეთ ფქვილს და მარილს, მოზილეთ ცომი.","დატოვეთ მაცივარში 1 საათი.","კარაქი ჩამოაყალიბეთ კვადრატად, ცომი გახეხეთ და გახვიეთ კარაქზე.","გახეხეთ, გახსენით სამად, გააგრილეთ — გაიმეორეთ 3-ჯერ.","გახეხეთ თხელად, დაჭერით სამკუთხედებად და გახვიეთ კრუასანებად.","დატოვეთ 2 საათი და გამოაცხვეთ 200 გრადუსზე 15-18 წუთი კვერცხით მოპირკეთებული."]'::jsonb,
 240, ARRAY['breakfast','dessert'], 'https://images.unsplash.com/photo-1555507036-ab1f4038808a?w=1200&q=80'),
('თურქული შაქშუკა', 'ცხარე პომიდვრის სოუსში ჩაშუშული კვერცხი — ახლო აღმოსავლური საუზმე ერთი ტაფიდან.',
 '["კვერცხი 4 ცალი","პომიდორი 500 გრ","წითელი ბულგარული წიწაკა 2 ცალი","ხახვი 1 ცალი","ნიორი 3 კბილი","პაპრიკა 1 ჩ.კ.","ძირაკი 1 ჩ.კ.","ცხარე პაპრიკა","ფეტა 100 გრ","ქინძი","ზეთისხილის ზეთი"]'::jsonb,
 '["ცხელ ტაფაზე ზეთისხილის ზეთით მოშუშეთ ხახვი და ბულგარული წიწაკა.","დაუმატეთ ნიორი და სანელებლები.","ჩააგდეთ გახეხილი პომიდვრები, მოხარშეთ 15 წუთი სქელ სოუსამდე.","კოვზით გააკეთეთ 4 ღრმული და თითოში ჩატეხეთ თითო კვერცხი.","დახურეთ სახურავი და მოხარშეთ 5-7 წუთი სანამ თეთრი არ დაიჭერს.","ზემოდან მოაყარეთ ფეტა და ქინძი, მიაწოდეთ პიტასთან."]'::jsonb,
 30, ARRAY['breakfast','lunch'], 'https://images.unsplash.com/photo-1590412200988-a436970781fa?w=1200&q=80'),
('პიცა მარგარიტა', 'ნეაპოლის სამი ფერი — წითელი პომიდორი, თეთრი მოცარელა, მწვანე ბაზილიკი.',
 '["ფქვილი 500 გრ","წყალი 320 მლ","საფუარი 3 გრ","მარილი 12 გრ","სან მარცანოს პომიდორი 400 გრ","მოცარელა ბუფალო 250 გრ","ახალი ბაზილიკი","ზეთისხილის ზეთი"]'::jsonb,
 '["წყალში გახსენით საფუარი, დაუმატეთ ფქვილი და მარილი, მოზილეთ ცომი.","დატოვეთ 24 საათი მაცივარში ნელი დუღილისთვის.","ცომი გაყავით 4 ბურთად, დატოვეთ ოთახის ტემპერატურაზე 2 საათი.","პომიდვრები ხელით დაფშვნით, დაუმატეთ ცოტა მარილი.","გახეხეთ ცომი, დაუსვით სოუსი, დაანაწილეთ მოცარელა.","გამოაცხვეთ 260+ გრადუსზე 6-8 წუთი, ცხელს დაუმატეთ ბაზილიკი და ზეთი."]'::jsonb,
 90, ARRAY['dinner','lunch'], 'https://images.unsplash.com/photo-1574071318508-1cdbab80d002?w=1200&q=80'),
('ბერძნული სალათი', 'ეგეოსური ზაფხულის გემო — მკვრივი პომიდვრები, კიტრი, ფეტა და კალამატა ზეთისხილი.',
 '["პომიდორი 4 ცალი","კიტრი 1 ცალი","წითელი ხახვი 1 ცალი","ბულგარული წიწაკა 1 ცალი","ფეტა 200 გრ","კალამატის ზეთისხილი 80 გრ","ორეგანო","ზეთისხილის ზეთი 4 კოვზი","წითელი ღვინის ძმარი 1 კოვზი"]'::jsonb,
 '["პომიდვრები დაჭერით მსხვილ ნაჭრებად.","კიტრი და წიწაკა დაჭერით ნახევარმთვარეებად.","წითელი ხახვი დაჭერით თხელი რგოლებით.","ყველაფერი მოათავსეთ ღრმა თასში, ზემოდან დაადეთ ფეტას მთლიანი კუბი.","მოაყარეთ ზეთისხილი და ორეგანო.","ზეთი და ძმარი აურიეთ, გადაასხით ზემოდან. მარილი გემოვნებით."]'::jsonb,
 15, ARRAY['lunch','dinner'], 'https://images.unsplash.com/photo-1540189549336-e6e99c3679fe?w=1200&q=80'),
('ტირამისუ', 'იტალიური კრემისებრი დესერტი — მასკარპონე, ესპრესო და კაკაო შრეებად.',
 '["სავოიარდი 24 ცალი","მასკარპონე 500 გრ","კვერცხი 4 ცალი","შაქარი 100 გრ","ესპრესო 300 მლ (გაცივებული)","მარსალას ღვინო 3 კოვზი","კაკაოს ფხვნილი"]'::jsonb,
 '["კვერცხის გულები ცემეთ შაქართან სანამ არ გახდება ღია და ფუმფულა.","დაუმატეთ მასკარპონე და მარსალა, ერთგვაროვნად აურიეთ.","ცილები ცალკე მოცემეთ მკვრივ ქაფად და ფაქიზად შეურიეთ კრემში.","სავოიარდი სწრაფად ჩააგდეთ ესპრესოში და ჩააწყვეთ ფორმის ბოლოში.","ზემოდან დაასხით კრემის ნახევარი, გაიმეორეთ შრე.","გააცივეთ სულ მცირე 4 საათი და მოაყარეთ კაკაო მიწოდებამდე."]'::jsonb,
 30, ARRAY['dessert'], 'https://images.unsplash.com/photo-1571877227200-a0d98ea607e9?w=1200&q=80'),
('ამერიკული ბლინი', 'ფუმფულა, სქელი პანქეიქები ნეკერჩხლის სიროპითა და კარაქით — შაბათის საუზმე.',
 '["ფქვილი 250 გრ","რძე 300 მლ","კვერცხი 2 ცალი","შაქარი 40 გრ","საცხობი ფხვნილი 2 ჩ.კ.","მარილი 1 ჩ.კ.","კარაქი 40 გრ დამდნარი","ნეკერჩხლის სიროპი","ხილი მიწოდებისთვის"]'::jsonb,
 '["მშრალი ინგრედიენტები კარგად აურიეთ ცალკე თასში.","რძეს დაუმატეთ კვერცხი და დამდნარი კარაქი, აურიეთ.","სველი და მშრალი ერთმანეთს შეურიეთ — ცომი უნდა იყოს ცოტა კოშტიანი, ზედმეტად ნუ აურევთ.","ცხელ, ცოტა ცხიმიან ტაფაზე ჩაასხით ნახევარი ნახევარი კოვზი ცომი.","როცა ბუშტები გამოჩნდება, გადააბრუნეთ და მოხარშეთ კიდევ 1 წუთი.","დააწყვეთ თეფშზე, ზემოდან დაასხით სიროპი და დაუმატეთ ხილი."]'::jsonb,
 25, ARRAY['breakfast'], 'https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=1200&q=80'),
('ვიეტნამური ფო ბო', 'არომატული ბულიონი, ბრინჯის ლაფშა და საქონლის თხელი ნაჭრები — ჰანოის ქუჩის კლასიკა.',
 '["საქონლის ძვლები 1 კგ","საქონლის ფილე 300 გრ","ბრინჯის ლაფშა 300 გრ","ხახვი 2 ცალი","ჯანჯაფილი 50 გრ","დარიჩინი 1 ჯოხი","ვარსკვლავიანი ანისი 3 ცალი","მიხაკი 4 ცალი","თევზის სოუსი 3 კოვზი","ლაიმი","ბაზილიკი, ქინძი","ცხარე წიწაკა"]'::jsonb,
